{
  "hooks": {
    "SessionStart": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "[ ! -f \"$CLAUDE_PROJECT_DIR\"/.crank/hooks/session-start.ts ] || bun --env-file=/dev/null \"$CLAUDE_PROJECT_DIR\"/.crank/hooks/session-start.ts",
            "timeout": 10
          }
        ]
      }
    ],
    "PostToolUse": [
      {
        "matcher": "Write|Edit|MultiEdit",
        "hooks": [
          {
            "type": "command",
            "command": "[ ! -f \"$CLAUDE_PROJECT_DIR\"/.crank/hooks/post-write.ts ] || bun --env-file=/dev/null \"$CLAUDE_PROJECT_DIR\"/.crank/hooks/post-write.ts",
            "timeout": 10
          }
        ]
      },
      {
        "matcher": "Read|Bash",
        "hooks": [
          {
            "type": "command",
            "command": "[ ! -f \"$CLAUDE_PROJECT_DIR\"/.crank/hooks/post-read.ts ] || bun --env-file=/dev/null \"$CLAUDE_PROJECT_DIR\"/.crank/hooks/post-read.ts",
            "timeout": 10
          }
        ]
      }
    ],
    "Stop": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "[ ! -f \"$CLAUDE_PROJECT_DIR\"/.crank/hooks/stop.ts ] || bun --env-file=/dev/null \"$CLAUDE_PROJECT_DIR\"/.crank/hooks/stop.ts",
            "timeout": 10
          }
        ]
      }
    ],
    "SessionEnd": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "[ ! -f \"$CLAUDE_PROJECT_DIR\"/.crank/hooks/session-end.ts ] || bun --env-file=/dev/null \"$CLAUDE_PROJECT_DIR\"/.crank/hooks/session-end.ts",
            "timeout": 10
          }
        ]
      }
    ],
    "SubagentStart": [
      {
        "matcher": "^(general-purpose|Explore|Plan|workflow-subagent)$",
        "hooks": [
          {
            "type": "command",
            "command": "[ ! -f \"$CLAUDE_PROJECT_DIR\"/.crank/hooks/subagent-start.ts ] || bun --env-file=/dev/null \"$CLAUDE_PROJECT_DIR\"/.crank/hooks/subagent-start.ts",
            "timeout": 10
          }
        ]
      }
    ]
  },
  "permissions": {
    "allow": [
      "Bash(crank-mem search *)",
      "Bash(crank-mem timeline *)",
      "Bash(crank-mem get *)",
      "Bash(crank-mem outline *)",
      "Bash(crank-mem unfold *)"
    ]
  }
}

